// Test DeleGator decoding specifically
async function testDeleGator() {
  const sample = {
    name: 'Sepolia TX 2 - DeleGator',
    url: 'https://sepolia.etherscan.io/tx/0x2eca4eb7ae55dcc419c0e21ac34a3e57731b2bb5825bef9048afb1e55d0dccd0',
    contractAddress: '0x5315eb7f03465aa2aef2fe052b8eed2cab0741a0',
    bytecode: ''
  };

  console.log('Testing DeleGator decoding with detailed output...\n');
  console.log('Bytecode length:', sample.bytecode.length);
  console.log('Selector:', sample.bytecode.slice(0, 10));

  try {
    const response = await fetch('http://localhost:3000/api/decompile', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        bytecode: sample.bytecode,
        contractAddress: sample.contractAddress,
        chainId: 11155111
      }),
    });

    const responseText = await response.text();
    console.log('\nRaw response:', responseText);

    try {
      const result = JSON.parse(responseText);
      console.log('\nParsed result:', JSON.stringify(result, null, 2));
    } catch (e) {
      console.log('Failed to parse JSON response');
    }
  } catch (error) {
    console.log('Request failed:', error);
  }
}

testDeleGator().catch(console.error);